with filtered as (select *, case when amount >= 1550 then 'High' when amount >= 410 then 'Medium' else 'Low' end as amount_level, round(amount * 1.1, 2) as adjusted_amount, coalesce(method, 'OTHER') as method_filled from payments where paid_at > timestamp '2023-05-27 10:00:00' and method is not null), valid as (select id, order_id, method, amount, paid_at, status, method_filled, case when adjusted_amount >= 86 then 'High' when adjusted_amount >= 16 then 'Medium' else 'Low' end as adjusted_amount_band, coalesce(method, 'OTHER') as resolved_method from filtered where paid_at > date '2023-07-31'), gaps as (select *, case when paid_at - lag(paid_at) over (partition by order_id order by paid_at, id) > interval '14' day then 1 else 0 end as session_start_flag from valid), sessions_payments as (select *, sum(session_start_flag) over (partition by order_id order by paid_at, id rows between unbounded preceding and current row) as session_no from gaps), scored as (select id, order_id, amount, status, method_filled, adjusted_amount_band, resolved_method, session_start_flag, sum(session_start_flag) over w_recent as last4_sum_session_start_flag, min(session_start_flag) over w_recent as last4_min_session_start_flag, max(session_start_flag) over w_recent as last4_max_session_start_flag from sessions_payments where amount < 950 window w_recent as (partition by method order by session_start_flag, id rows between 3 preceding and current row)), enriched as (select id, order_id, amount, status, last4_sum_session_start_flag, lead(last4_max_session_start_flag) over (partition by order_id order by last4_max_session_start_flag, id) as next_last4_max_session_start_flag, lag(last4_max_session_start_flag) over (partition by order_id order by last4_max_session_start_flag, id) as prev_last4_max_session_start_flag, lead(last4_min_session_start_flag) over (partition by order_id order by last4_max_session_start_flag, id) as next_last4_min_session_start_flag, lag(last4_min_session_start_flag) over (partition by order_id order by last4_max_session_start_flag, id) as prev_last4_min_session_start_flag, row_number() over (partition by order_id order by last4_max_session_start_flag, id) as row_seq from scored), enriched_payments as (select s.id, s.order_id, s.last4_sum_session_start_flag, s.next_last4_max_session_start_flag, s.prev_last4_max_session_start_flag, s.next_last4_min_session_start_flag, o.status as order_status from enriched s left join orders o on s.order_id = o.id), with_windows as (select *, row_number() over (partition by order_id order by last4_sum_session_start_flag, id) as seq_no, sum(prev_last4_max_session_start_flag) over w_grp as running_prev_last4_max_session_start_flag, sum(next_last4_min_session_start_flag) over (order by last4_sum_session_start_flag, id rows between unbounded preceding and current row) as cumulative_next_last4_min_session_start_flag, sum(next_last4_max_session_start_flag) over w_grp as running_next_last4_max_session_start_flag, row_number() over (partition by order_status, order_id order by next_last4_max_session_start_flag desc, id) as row_seq from enriched_payments window w_grp as (partition by order_id order by next_last4_max_session_start_flag, id rows between unbounded preceding and current row)) select * from (select id, order_id, prev_last4_max_session_start_flag, last4_sum_session_start_flag, next_last4_max_session_start_flag from with_windows) src unpivot (val for metric_name in (prev_last4_max_session_start_flag as PREV_LAST4_MAX_SESSION_START_FLAG, last4_sum_session_start_flag as LAST4_SUM_SESSION_START_FLAG_VAL, next_last4_max_session_start_flag as NEXT_LAST4_MAX_SESSION_START_FLAG)) unp;
